class BusinessRetentionTests(unittest.TestCase):
    def test_both_cleanup_paths_remove_all_known_payloads_and_preserve_other_business(self):
        for variant in (None,0):
            row=CATALOG['bereinigung'];s=solved_record(row,actions=row['solution'] if variant is None else row['variants'][variant]['actions']);self.assertTrue(assess(s)['passed'])
            related=business_related(s,'cloud','cloud-auszug');self.assertEqual(related['local'],{'angebot-lokal','lokaler-auszug'});self.assertEqual(related['cloud'],{'angebot-lokal','cloud-auszug'})
            for docs,keys in [(s['documents'],related['cloud']),(s['onprem']['documents'],related['local']),(s['local_migration']['documents'],related['stage'])]:
                for key in keys:self.assertEqual((docs[key]['name'],docs[key]['content'],docs[key]['versions'],docs[key]['deleted']),('[Entfernt]','',[],True))
            for point in s['onprem']['backup']['points']:
                for key in related['local']&set(point['documents']):self.assertEqual(point['documents'][key]['content'],'')
                self.assertEqual(point['orders']['LP-1001']['customer'],'[Entfernt]')
            self.assertEqual(s['orders']['NL-1001']['amount'],120);self.assertEqual(s['onprem']['documents']['personal-lokal']['content'],'Ausschließlich fiktive lokale Personaldaten.')

