    def test_trainer_progress_spans_exercises_without_overwriting_them(self):
        self.post(self.trainer,'import',dict(save=dict(format='nordlicht-save/v1',state=solve_example('intro'))))
        self.post(self.trainer,'check')
        self.post(self.trainer,'select_task',dict(id='02'))
