        self.post(self.trainer,'reply',dict(text='Ich untersuche Region und Tags.'))
        before=self.request('/api/state',token=self.trainer)
        overview=self.post(self.trainer,'progress_overview')['result']
        solo=next(row for row in overview['instances'] if row['id']=='solo')
        self.assertEqual(solo['totals']['visited'],2);self.assertEqual(solo['totals']['passed'],1)
        detail=self.post(self.trainer,'progress_detail',dict(target='solo'))['result']
        self.assertEqual(detail['format'],'nordlicht-progress/v1')
        second=next(row for row in detail['exercises'] if row['task']=='02')
        self.assertEqual(second['hints_used'],1);self.assertEqual(second['notes'],'Projektregel verstanden')
        self.assertEqual(second['reply'],'Ich untersuche Region und Tags.')
