def authored_reference_course():
    data=copy.deepcopy(DEFAULT_COURSE_DATA);row=copy.deepcopy(next(r for r in data['tasks'] if r['id']=='intro'));row.update(id='author-ref',title='Ergänzte Referenzübung');row['solution'].append(dict(action='workload',value={'$state':['minute']}));indices={}
    for key,point in [('missing',{'$state':['backup','points',0,'id']}),('literal','not-a-point')]:
        indices[key]=len(row['failures']);row['failures'].append(dict(label='Referenzprobe '+key,rationale='Ohne vorhandenen Punkt nicht wiederherstellbar.',outcome='rejected',actions=[dict(action='restore',point=point,id='offer',target='reference-copy'),dict(action='advance',minutes=100)]))
    data['tasks'].append(row);return data,indices


