class ContainerRuntimeTests(unittest.TestCase):
    def deployed(self):
        s=fresh();s,_=act(s,'create',id='parcel',name='Parcel service',kind='Container Apps',group='rg-lab',ip='10.20.1.61',subnet='app')
        s,_=act(s,'configure',id='parcel',changes=dict(image='shipping:1.0',port=8080,configured=True))
        s,_=act(s,'container_config',id='parcel',values=dict(DB_HOST='db',DOCUMENT_ID='offer'))
        return s

    def test_any_container_requires_shipping_image_port_and_configuration(self):
        s=self.deployed();self.assertTrue(connection(s,source='parcel',host='parcel',port=8080)['allowed'])
        for field,value in [('image','shipping:broken'),('image','orders:1.0'),('port',443),('configured',False)]:
            with self.subTest(field=field,value=value):
                changed,_=act(s,'configure',id='parcel',changes={field:value})
                self.assertFalse(metrics(changed,'parcel')['available'])
                result=connection(changed,source='parcel',host='parcel',port=changed['resources']['parcel']['port'])
                self.assertFalse(result['allowed']);self.assertTrue(result['path'])
        failed,_=act(s,'configure',id='parcel',changes=dict(image='shipping:broken',instances=10))
        self.assertFalse(metrics(failed,'parcel')['available']);self.assertIn('Image',connection(failed,source='parcel',host='parcel',port=8080)['path'][-1])

    def test_created_container_obeys_actual_data_network_capacity_and_zone(self):
        s=self.deployed();self.assertTrue(metrics(s,'parcel')['available'])
        for target,changes in [('db',dict(status='stopped')),('db',dict(configured=False)),('storage',dict(used_gb=100))]:
            with self.subTest(target=target,changes=changes):
                bad,_=act(s,'configure',id=target,changes=changes)
                self.assertFalse(metrics(bad,'parcel')['available']);self.assertFalse(connection(bad,source='parcel',host='parcel',port=8080)['allowed'])
        bad,_=act(s,'rule_add',rule=dict(id='parcel-db-deny',direction='Outbound',protocol='TCP',source=s['resources']['parcel']['ip'],destination='db',port=s['resources']['db']['port'],action='Deny',priority=100))
        self.assertFalse(connection(bad,source='parcel',host='parcel',port=8080)['allowed'])
        high,_=act(s,'configure',id='parcel',changes=dict(size='B1'));high['workload']=100;validate(high)
        self.assertGreater(metrics(high,'parcel')['error_rate'],0);self.assertFalse(connection(high,source='parcel',host='parcel',port=8080)['allowed'])
        high,_=act(high,'configure',id='parcel',changes=dict(instances=3));self.assertTrue(connection(high,source='parcel',host='parcel',port=8080)['allowed'])
        incident,_=act(s,'availability_event',region='germanywestcentral',zone=1,enabled=True)
        self.assertFalse(metrics(incident,'parcel')['available'])

    def test_container_vm_storage_controls_refused_atomically(self):
        s=self.deployed();original=copy.deepcopy(s)
        for field,value in [('os','Windows'),('disk_gb',512),('tier','cool'),('redundancy','GRS'),('capacity_gb',300),('used_gb',1),('status','deallocated')]:
            with self.subTest(field=field):
                with self.assertRaises(Invalid):act(s,'configure',id='parcel',changes={'name':'Must not save',field:value})
                self.assertEqual(s,original)
        with self.assertRaises(Invalid):act(s,'power',id='parcel',operation='deallocate')
        self.assertEqual(s,original)

    def test_container_start_stop_cost_and_legacy_fields_are_explicit(self):
        s=self.deployed();before=copy.deepcopy(s);running=next(r for r in hourly(s) if r['resource']=='parcel')['compute']
        s,_=act(s,'power',id='parcel',operation='shutdown');self.assertFalse(metrics(s,'parcel')['available']);self.assertEqual(next(r for r in hourly(s) if r['resource']=='parcel')['compute'],running)
        s,_=act(s,'power',id='parcel',operation='start');self.assertTrue(metrics(s,'parcel')['available'])
        legacy=copy.deepcopy(before);legacy['resources']['parcel'].update(status='deallocated',os='Historical OS',disk_gb=777);validate(legacy)
        self.assertEqual(upgrade_snapshot(legacy),legacy)
        changed,_=act(legacy,'configure',id='parcel',changes=dict(owner='New owner'))
        for field in ('status','os','disk_gb'):self.assertEqual(changed['resources']['parcel'][field],legacy['resources']['parcel'][field])
        self.assertEqual(next(r for r in hourly(changed) if r['resource']=='parcel')['compute'],0)
        changed,_=act(changed,'power',id='parcel',operation='start');self.assertEqual(next(r for r in hourly(changed) if r['resource']=='parcel')['compute'],running)
        self.assertEqual(changed['resources']['parcel']['disk_gb'],777)

    def test_core_container_profile_and_other_runtime_stay_distinct(self):
        s=solve_example('16');self.assertTrue(assess(s)['passed']);self.assertTrue(connection(s,host='versand.intern',port=8080)['allowed'])
        bad,_=act(s,'configure',id='container',changes=dict(image='orders:1.0'))
        self.assertFalse(connection(bad,host='versand.intern',port=8080)['allowed']);self.assertFalse(assess(bad)['passed'])
        self.assertTrue(connection(bad,host='auftrag.intern')['allowed'])


