class OrderRuntimeTests(unittest.TestCase):
    def own(self,kind='VM'):
        s=fresh();s,_=act(s,'create',id='ownorders',name='Own orders',kind=kind,group='rg-app',ip='10.20.1.61',subnet='app');dns=copy.deepcopy(s['network']['dns']);dns['auftrag.intern']='ownorders';s,_=act(s,'network',changes=dict(dns=dns));return s

    def test_created_vm_and_paas_open_and_edit_same_orders_with_separate_rights(self):
        for kind in ('VM','App Service'):
            with self.subTest(kind=kind):
                s=self.own(kind);self.assertTrue(application_access(s)['allowed']);self.assertFalse(application_access(s,user='partner')['allowed']);self.assertFalse(application_access(s,mfa=False)['allowed']);before=copy.deepcopy(s['orders']);row=order_application(s)['orders'][0];self.assertEqual(len(order_application(s)['orders']),len(before))
                changed,_=act(s,'order_update',id=row['id'],version=row['version'],changes=dict(subject='Actually edited on own runtime'),user='u11',mfa=True,source='hq')
                self.assertEqual(changed['orders'][row['id']]['subject'],'Actually edited on own runtime');self.assertEqual(changed['orders'][row['id']]['version'],row['version']+1)
                dns=copy.deepcopy(changed['network']['dns']);dns['auftrag.intern']='web';back,_=act(changed,'network',changes=dict(dns=dns));self.assertEqual(order_application(back)['orders'][0]['subject'],'Actually edited on own runtime')
                self.assertEqual(changed['roles'],s['roles']);self.assertEqual(changed['documents'],s['documents'])

    def test_created_orders_image_port_capacity_and_data_dependencies_are_real(self):
        for kind in ('VM','App Service'):
            s=self.own(kind)
            for target,changes in [('ownorders',dict(image='orders:broken')),('ownorders',dict(port=8080)),('ownorders',dict(configured=False)),('db',dict(configured=False)),('storage',dict(used_gb=100))]:
                with self.subTest(kind=kind,target=target,changes=changes):
                    bad,_=act(s,'configure',id=target,changes=changes);self.assertFalse(connection(bad)['allowed']);self.assertFalse(metrics(bad,'ownorders')['available']);self.assertFalse(application_access(bad)['allowed'])
            bad,_=act(s,'rule_add',rule=dict(id='own-db-deny',direction='Outbound',protocol='TCP',source='ownorders',destination='db',port=s['resources']['db']['port'],action='Deny',priority=100));self.assertFalse(application_access(bad)['allowed'])
            bad,_=act(s,'configure',id='ownorders',changes=dict(size='B1'));self.assertGreater(metrics(bad,'ownorders')['error_rate'],0);self.assertFalse(connection(bad)['allowed']);fixed,_=act(bad,'configure',id='ownorders',changes=dict(instances=2));self.assertTrue(application_access(fixed)['allowed'])

    def test_created_order_service_identity_and_data_roles_are_not_implied_by_management(self):
        s=self.own();bad,_=act(s,'service_identity',id='orders-app',changes=dict(active=False));self.assertFalse(application_access(bad)['allowed'])
        bad,_=act(s,'role_remove',principal='orders-app',role='Blob Reader',scope='sales');self.assertFalse(application_access(bad)['allowed'])
        bad,_=act(s,'role_remove',principal='Vertrieb',role='Order Operator',scope='orders');self.assertFalse(application_access(bad)['allowed']);self.assertTrue(connection(bad)['allowed'])
        bad,_=act(bad,'role_add',principal='u11',role='Contributor',scope='ownorders');self.assertFalse(application_access(bad)['allowed'])

    def test_request_shipping_storage_and_saas_do_not_become_orders_by_dns(self):
        from domain import runtime_profile
        s=fresh();s,_=act(s,'request_deploy',model='PaaS',reason='Separate customer requests')
        self.assertEqual(runtime_profile(s,'requestpaas'),'requests')
        for key in ('requestpaas','saas','storage','container'):
            dns=copy.deepcopy(s['network']['dns']);dns['auftrag.intern']=key;bad,_=act(s,'network',changes=dict(dns=dns));self.assertFalse(application_access(bad)['allowed'],key)
        self.assertEqual(runtime_profile(self.own(),'ownorders'),'orders')

    def test_app_service_ignored_vm_storage_fields_refused_legacy_preserved(self):
        s=self.own('App Service');old=copy.deepcopy(s);old['resources']['ownorders'].update(os='Historical platform',disk_gb=777);validate(old);self.assertEqual(upgrade_snapshot(old),old)
        for field,value in [('os','Windows'),('disk_gb',1),('tier','cool'),('redundancy','GRS'),('capacity_gb',400),('used_gb',1)]:
            with self.subTest(field=field):
                with self.assertRaises(Invalid):act(old,'configure',id='ownorders',changes={'name':'Must not persist',field:value})
        changed,_=act(old,'configure',id='ownorders',changes=dict(owner='New owner'));self.assertEqual(changed['resources']['ownorders']['os'],'Historical platform');self.assertEqual(changed['resources']['ownorders']['disk_gb'],777)
        self.assertTrue(application_access(changed)['allowed'])

    def test_owned_architecture_variants_have_actual_type_budget_and_fresh_probes(self):
        row=CATALOG['20'];self.assertEqual(len(row['variants']),3)
        for variant in row['variants']:
            solved=solved_record(row,actions=variant['actions']);self.assertTrue(assess(solved)['passed']);self.assertLessEqual(monthly(solved),500)
            if resolve_target(solved) not in ('web','paas'):
                wrong,_=act(solved,'decision',key='architecture',value='IaaS' if solved['decisions']['architecture']=='PaaS' else 'PaaS');self.assertFalse(assess(wrong)['passed'])
        s=self.own();before=copy.deepcopy(s);row=next(r for r in hourly(s) if r['resource']=='ownorders');self.assertEqual(row['traffic'],s['workload']*s['tariffs']['traffic_load_hour']);self.assertEqual(s,before)


class DatabaseControlTests(unittest.TestCase):
    def test_ignored_vm_storage_fields_and_deallocation_refused_atomically(self):
        s=fresh();before=copy.deepcopy(s)
        for key,value in [('os','Windows'),('disk_gb',1000),('image','database:broken'),('tier','cool'),('redundancy','GRS'),('capacity_gb',1),('used_gb',9999),('status','deallocated')]:
            with self.subTest(key=key):
                with self.assertRaises(Invalid):act(s,'configure',id='db',changes={'name':'Must not save',key:value})
                self.assertEqual(s,before)
        with self.assertRaises(Invalid):act(s,'power',id='db',operation='deallocate')
        self.assertEqual(s,before)

    def test_db_stop_start_propagates_to_orders_container_and_request_without_rollback(self):
        s=model_solution('PaaS');s,_=act(s,'configure',id='container',changes=dict(image='shipping:1.0',port=8080));self.assertTrue(request_access(s)['allowed']);self.assertTrue(application_access(s)['allowed']);self.assertTrue(metrics(s,'container')['available']);before=copy.deepcopy(s)
        stopped,_=act(s,'power',id='db',operation='shutdown');self.assertFalse(application_access(stopped)['allowed']);self.assertFalse(request_access(stopped)['allowed']);self.assertFalse(metrics(stopped,'container')['available'])
        self.assertEqual(next(r for r in hourly(stopped) if r['resource']=='db'),next(r for r in hourly(s) if r['resource']=='db'))
        restored,_=act(stopped,'power',id='db',operation='start');self.assertTrue(application_access(restored)['allowed']);self.assertTrue(request_access(restored)['allowed']);self.assertTrue(metrics(restored,'container')['available'])
        for key in ('minute','cost','cost_ledger','metrics','alerts','documents','orders','tariffs'):self.assertEqual(restored[key],before[key],key)

    def test_legacy_ignored_values_and_deallocated_status_retained_until_explicit_start(self):
        old=fresh();old['resources']['db'].update(os='Historical platform',disk_gb=1000,image='database:broken',tier='cool',redundancy='GRS',capacity_gb=1,used_gb=9999,status='deallocated');validate(old);self.assertEqual(upgrade_snapshot(old),old)
        changed,_=act(old,'configure',id='db',changes=dict(owner='New owner'))
        for key in ('os','disk_gb','image','tier','redundancy','capacity_gb','used_gb','status'):self.assertEqual(changed['resources']['db'][key],old['resources']['db'][key])
        self.assertEqual(next(r for r in hourly(changed) if r['resource']=='db')['compute'],0)
        started,_=act(changed,'power',id='db',operation='start');self.assertTrue(application_access(started)['allowed']);self.assertGreater(next(r for r in hourly(started) if r['resource']=='db')['compute'],0)
        self.assertEqual(started['resources']['db']['disk_gb'],1000)

    def test_class_instance_price_and_zone_availability_without_fake_db_metrics(self):
        s=fresh();price=next(r for r in hourly(s) if r['resource']=='db')['compute'];s,_=act(s,'configure',id='db',changes=dict(size='B1',instances=2,availability='zones'));self.assertEqual(next(r for r in hourly(s) if r['resource']=='db')['compute'],price)
        self.assertFalse(metrics(s,'db')['supported']);self.assertFalse(metrics(s,'db')['available'])
        s,_=act(s,'availability_event',region='germanywestcentral',zone=1,enabled=True)
        from domain import resource_availability
        self.assertEqual(resource_availability(s,'db')['online'],1);self.assertEqual(next(r for r in hourly(s) if r['resource']=='db')['compute'],price)
        s,_=act(s,'configure',id='db',changes=dict(instances=1));self.assertEqual(resource_availability(s,'db')['online'],0)

    def test_direct_port_and_real_nsg_path_while_profiles_use_saved_db_port(self):
        s=solve_example('16');self.assertTrue(connection(s,source='web',host='daten.intern',port=5432)['allowed']);s,_=act(s,'configure',id='db',changes=dict(port=15432))
        self.assertFalse(connection(s,source='web',host='daten.intern',port=5432)['allowed']);self.assertTrue(connection(s,source='web',host='daten.intern',port=15432)['allowed']);self.assertTrue(application_access(s)['allowed']);self.assertTrue(metrics(s,'container')['available'])
        s,_=act(s,'rule_add',rule=dict(id='db-new-port',direction='Inbound',protocol='TCP',source='VirtualNetwork',destination='db',port=15432,action='Deny',priority=100));self.assertFalse(application_access(s)['allowed']);self.assertFalse(metrics(s,'container')['available'])

    def test_other_resource_type_cannot_impersonate_company_database(self):
        for kind in ('Storage','VM','App Service'):
            s=model_solution('PaaS');s,_=act(s,'configure',id='container',changes=dict(image='shipping:1.0',port=8080));s['resources']['db']['kind']=kind;validate(s);original=copy.deepcopy(s)
            self.assertFalse(connection(s,source='web',host='db',port=5432)['allowed']);self.assertFalse(application_access(s)['allowed']);self.assertFalse(request_access(s)['allowed']);self.assertFalse(metrics(s,'container')['available']);self.assertEqual(s,original)



class DeliveryDocumentationTests(unittest.TestCase):
    def test_actual_cli_generates_complete_current_and_historical_docs(self):
        # The tiny runtime fixture proves CLI documentation ordering only, not runtime launch.
        import shutil, re, delivery
        with Scratch() as tmp:
            base=Path(tmp); stage=base/'source'; stage.mkdir(); runtime=base/'runtime-fixture'
            (runtime/'DLLs').mkdir(parents=True); (runtime/'Lib').mkdir()
            (runtime/'python.exe').write_bytes(b'documentation-only fixture, never executed')
            (runtime/'Lib'/'fixture.py').write_text('# packaging fixture',encoding='utf-8')
            source_names=('__init__.py','domain.py','course.py','persistence.py','server.py','ui.py','delivery.py','test_simulator.py')
            for name in source_names:
                shutil.copyfile(Path(__file__).parent/name,stage/name)
            shutil.copytree(Path(__file__).parent/'static',stage/'static')
            package=base/'package'
            wrapper="import sys,runpy,os; source,base,out=sys.argv[1:]; sys.path.insert(0,os.path.dirname(source)); sys.base_prefix=base; sys.argv=[source,out]; runpy.run_path(source,run_name='__main__')"
            result=subprocess.run([sys.executable,'-X','utf8','-B','-c',wrapper,str(stage/'delivery.py'),str(runtime),str(package)],capture_output=True,encoding='utf-8',timeout=90)
            self.assertEqual(result.returncode,0,result.stdout+result.stderr)
            expected={'STARTANLEITUNG.md':delivery.QUICKSTART,'UNTERRICHT.md':delivery.CLASSROOM_GUIDE,'MODELLGRENZEN.md':delivery.MODEL_GUIDE,'AUFGABE_ERGAENZEN.md':delivery.AUTHORING_GUIDE,'DETAILARCHIV.md':delivery.ARCHIVE_HEADER+delivery.GUIDE,'KURSWEG.md':delivery.COURSE_PATH,'TECHNIK.md':delivery.TECH_GUIDE}
            for name,text in expected.items():
                self.assertEqual((package/name).read_text(encoding='utf-8'),text,name)
                for target in re.findall(r'\]\(([^)]+)\)',text):
                    if '://' not in target:self.assertTrue((package/target.split('#')[0]).is_file(),(name,target))
            self.assertLess(len(delivery.QUICKSTART.encode('utf-8')),10000)
            self.assertEqual((package/'START.cmd').read_text(encoding='utf-8'),delivery.START)
            self.assertEqual((package/'UNTERRICHTSSERVER.cmd').read_text(encoding='utf-8'),delivery.LAN)
            self.assertEqual({p.name for p in (package/'app').glob('*.py')},set(source_names))
