class FileVersionCapacityTests(unittest.TestCase):
    def test_historical_restore_requires_space_on_actual_blob_files_or_disk_host(self):
        for kind in ('Blob','Files','Disk'):
            with self.subTest(kind=kind):
                state=fresh();host='storage'
                if kind=='Files':
                    host='version-files';state,_=act(state,'create',id=host,name='Fiktive Dateifreigabe',kind='File Share',group='rg-data',subnet='data',ip='10.20.2.31')
                elif kind=='Disk':
                    host='web';state,_=act(state,'power',id=host,operation='start')
                    state,_=act(state,'configure',id=host,changes=dict(disk_gb=64,used_gb=12))
                if kind!='Blob':state,_=act(state,'storage_move',id='offer',kind=kind,host=host,reason='Fiktive Speicherprüfung')
                original=copy.deepcopy(state['documents']['offer']);state,_=act(state,'file_write',id='offer',content='Fiktive neue Fassung')
                maximum=state['resources'][host]['disk_gb' if kind=='Disk' else 'capacity_gb']
                state,_=act(state,'configure',id=host,changes=dict(used_gb=maximum));before=copy.deepcopy(state)
                for action,params in [('file_write',dict(content='Fiktiv')),('version_restore',dict(version=1))]:
                    with self.assertRaises(Invalid):act(state,action,id='offer',**params)
                    self.assertEqual(state,before)
                deleted,_=act(state,'file_delete',id='offer');self.assertTrue(deleted['documents']['offer']['deleted'])
                self.assertEqual(deleted['documents']['offer']['version'],3)
                state,_=act(state,'configure',id=host,changes=dict(used_gb=12));restored,_=act(state,'version_restore',id='offer',version=1)
                self.assertEqual(restored['documents']['offer']['content'],original['content'])
                self.assertEqual(restored['documents']['offer']['version'],3)
                self.assertEqual(restored['documents']['offer']['versions'][-1]['content'],'Fiktive neue Fassung')
                self.assertEqual(restored['minute'],state['minute']);self.assertEqual(restored['cost'],state['cost'])

    def test_version_selection_is_exact_existing_integer_and_never_truncates(self):
        state=fresh();state,_=act(state,'file_write',id='offer',content='Fiktive Version2');before=copy.deepcopy(state)
        for version in (True,False,1.0,1.9,'1',None,-1,0,1000000001,999):
            with self.subTest(version=version):
                with self.assertRaises(Invalid):act(state,'version_restore',id='offer',version=version)
                self.assertEqual(state,before)
        with self.assertRaisesRegex(Invalid,'nicht vorhanden'):act(state,'version_restore',id='offer',version=999)
        restored,_=act(state,'version_restore',id='offer',version=1);self.assertEqual(restored['documents']['offer']['version'],3)
        for old_version in (0,999999998):
            with self.subTest(existing_stored_version=old_version):
                legacy=copy.deepcopy(state);legacy['documents']['offer']['versions'][0]['version']=old_version
                legacy['documents']['offer']['version']=max(2,old_version+1);validate(legacy)
                restored,_=act(legacy,'version_restore',id='offer',version=old_version)
                self.assertEqual(restored['documents']['offer']['content'],legacy['documents']['offer']['versions'][0]['content'])
                self.assertEqual(restored['documents']['offer']['version'],legacy['documents']['offer']['version']+1)
                self.assertEqual(legacy['documents']['offer']['versions'][0]['version'],old_version)


    def test_version_restore_retains_history_and_respects_login_and_repository(self):
        state=fresh();original=state['documents']['offer']['content'];state,_=act(state,'file_write',id='offer',content='Fiktive Version2')
        state,_=act(state,'file_delete',id='offer');before=copy.deepcopy(state)
        with self.assertRaises(Invalid):act(state,'version_restore',id='offer',version=1,actor='u60')
        self.assertEqual(state,before)
        unavailable,_=act(state,'configure',id='storage',changes=dict(configured=False))
        with self.assertRaises(Invalid):act(unavailable,'version_restore',id='offer',version=1)
        restored,_=act(state,'version_restore',id='offer',version=1);doc=restored['documents']['offer']
        self.assertEqual(doc['content'],original);self.assertFalse(doc['deleted']);self.assertEqual(doc['version'],4)
        self.assertEqual([v['version'] for v in doc['versions']],[1,2,3]);self.assertTrue(doc['versions'][-1]['deleted'])
        self.assertEqual(restored['data_governance'],state['data_governance']);self.assertEqual(restored['roles'],state['roles'])
